pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.roll(15);
        vm.warp(1000);

        address actor = address(0x1234);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 10 ether}("");

        assertTrue(success);

        assertTrue(address(c).balance == 0);
    }
}
